package io.zingg.duckdb.engine;
import io.zingg.duckdb.api.*; import org.duckdb.DuckDBConnection; import java.sql.*; import java.util.*; import java.util.concurrent.atomic.AtomicBoolean;
public final class DuckJob implements JobHandle { private final DuckDBConnection connection; private final JobId id; private final String connectionId; private final String schemaName; private final Runnable release; private final ResourceBudget budget; private final Set<String> materializedTables=Collections.synchronizedSet(new LinkedHashSet<>()); private final AtomicBoolean closed=new AtomicBoolean(); public DuckJob(DuckDBConnection c,JobId i){this(c,i,()->{},ResourceBudget.unlimited());} public DuckJob(DuckDBConnection c,JobId i,Runnable release){this(c,i,release,ResourceBudget.unlimited());} public DuckJob(DuckDBConnection c,JobId i,Runnable release,ResourceBudget budget){connection=c;id=i;connectionId="conn_"+UUID.randomUUID().toString();schemaName="_zingg_run_"+i.value().replace("-","");this.release=release;this.budget=budget==null?ResourceBudget.unlimited():budget;try(var s=connection.createStatement()){s.execute("CREATE SCHEMA "+DuckExpr.quote(schemaName));}catch(SQLException e){throw new DuckException("cannot create job schema",e);}} public JobId id(){return id;} public String connectionId(){return connectionId;} public String schemaName(){return schemaName;} public DuckDBConnection connection(){return connection;} ResourceBudget budget(){return budget;} void registerMaterialized(String name){materializedTables.add(name);} public Frame table(String name){return new DuckFrame(this,"SELECT * FROM "+DuckExpr.quote(schemaName)+"."+DuckExpr.quote(name),List.of(),RelationScope.WORKER_SHARED);} public Frame sql(String sql){if(sql==null||sql.isBlank())throw new DuckException("SQL is empty");return new DuckFrame(this,sql,List.of());} public void close(){if(closed.compareAndSet(false,true)){try{for(String name:materializedTables)try(var s=connection.createStatement()){s.execute("DROP TABLE IF EXISTS "+DuckExpr.quote(schemaName)+"."+DuckExpr.quote(name));}try(var s=connection.createStatement()){s.execute("DROP SCHEMA IF EXISTS "+DuckExpr.quote(schemaName));}finally{connection.close();}}catch(SQLException e){throw new DuckException("cannot close job",e);}finally{release.run();}}} }
